using HabitFlow.Application; using HabitFlow.Domain; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; namespace HabitFlow.Web.Controllers;
[Authorize] public class DashboardController(HabitService habits,ProgressService progress):Controller{public async Task<IActionResult> Index(){var user=DemoUser();var list=await habits.ListAsync(user.Id);return View(new DashboardDto(user.Name,list.Count(x=>!x.IsArchived),0,0,0,list.Select(x=>new HabitDto(x.Id,x.Name,x.Color,x.Category,false,x.IsArchived)).ToList()));} static User DemoUser()=>new(Guid.Parse("00000000-0000-0000-0000-000000000001"),"Usuário","user@habitflow.local","",null,UserRole.User,AccountStatus.Active,RiskStatus.Normal,UserPlan.Free,PlanStatus.Active,false,true,null,null,null,null,DateTime.UtcNow,DateTime.UtcNow);} 
[Authorize] public class HabitsController:Controller{public IActionResult Index()=>View();} [Authorize] public class ProgressController:Controller{public IActionResult Index()=>View();} [Authorize] public class ProfileController:Controller{public IActionResult Index()=>View();} [Authorize] public class SupportController:Controller{public IActionResult Index()=>View();} [Authorize(Roles="Admin")] public class AdminController:Controller{public IActionResult Index()=>View(); public IActionResult Users()=>View(); public IActionResult UserDetail()=>View(); public IActionResult Logs()=>View(); public IActionResult Settings()=>View();} [Authorize(Roles="Admin")] public class SettingsController:Controller{public IActionResult Index()=>RedirectToAction("Settings","Admin");} public class HealthController:Controller{public IActionResult Index()=>Ok(new{status="healthy"});}
